{"command":"python3 - <<'EOF'
import os, urllib.request, urllib.error

base = os.environ["ARTIFACT_SERVICE_URL"].rstrip("/")
token = os.environ["ARTIFACT_API_TOKEN"]
hdrs = {"Authorization": "Bearer " + token}

def go(label, path, method="GET", extra=None):
    h = dict(hdrs); h.update(extra or {})
    req = urllib.request.Request(base+path, method=method, headers=h)
    try:
        with urllib.request.urlopen(req, timeout=10) as r:
            print(label, "-> HTTP", r.status, r.read().decode()[:500])
    except urllib.error.HTTPError as e:
        print(label, "-> HTTP", e.code, e.read().decode()[:500])
    except Exception as e:
        print(label, "-> ERR", type(e).__name__, e)

go("GET quota", "/v1/quota")
go("GET releases", "/v1/projects/sqlite-utils/releases")
go("GET releases full", "/v1/projects/sqlite-utils/releases?version=4.1.1")
go("OPTIONS objects", "/v1/objects", method="OPTIONS")
EOF","description":"Probe other v1 routes and OPTIONS"}

{"command":"python3 - <<'EOF'
import os, urllib.request, urllib.error, urllib.parse

base = os.environ["ARTIFACT_SERVICE_URL"].rstrip("/")
token = os.environ["ARTIFACT_API_TOKEN"]
hdrs = {"Authorization": "Bearer " + token}

def go(label, path):
    req = urllib.request.Request(base+path, headers=hdrs)
    try:
        with urllib.request.urlopen(req, timeout=10) as r:
            print(label, "-> HTTP", r.status, r.read().decode()[:600])
    except urllib.error.HTTPError as e:
        print(label, "-> HTTP", e.code, e.read().decode()[:600])
    except Exception as e:
        print(label, "-> ERR", type(e).__name__, e)

for repo in ("pypi", "main", "default", "prod", "release", "sqlite-utils", "test"):
    go(f"quota repo={repo}", "/v1/quota?" + urllib.parse.urlencode({"repository": repo, "project": "sqlite-utils"}))
EOF","description":"Query quota and releases with repository names"}

