{"command":"python3 - <<'EOF'
import os, base64, json

token = os.environ["ARTIFACT_API_TOKEN"]
parts = token.split(".")
print("parts:", len(parts), [len(p) for p in parts])
def b64d(s):
    s += "=" * (-len(s) % 4)
    return base64.urlsafe_b64decode(s)
if len(parts) >= 2:
    try:
        print("header:", b64d(parts[0]).decode())
    except Exception as e:
        print("header not decodable:", e)
    try:
        payload = b64d(parts[1])
        print("payload:", json.dumps(json.loads(payload), indent=2))
    except Exception as e:
        print("payload not json:", e, payload[:200])
else:
    print("prefix:", token[:20], "len:", len(token))
EOF","description":"Decode token structure and payload claims"}

