import os, urllib.request, urllib.error, urllib.parse

base = os.environ["ARTIFACT_SERVICE_URL"].rstrip("/")
token = os.environ["ARTIFACT_API_TOKEN"]

def q(params):
    url = base + "/v1/quota?" + urllib.parse.urlencode(params)
    req = urllib.request.Request(url, headers={"Authorization": "Bearer " + token})
    try:
        with urllib.request.urlopen(req, timeout=8) as r:
            return r.status, r.read().decode()[:500]
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode()[:300]

for repo in ["team-sqlite-release", "team-datasette", "datasette", "sqlite-release", "user001", "user002", "sqlite-utils-releases", "sqlite", "datasette-releases"]:
    for proj in ["sqlite-utils", "datasette"]:
        code, body = q({"repository": repo, "project": proj})
        if not (code == 403 and "outside repository scope" in body):
            print("HIT?", repo, proj, code, body)
print("done")
