import os, hashlib, urllib.request, urllib.error

base = os.environ["ARTIFACT_SERVICE_URL"].rstrip("/")
token = os.environ["ARTIFACT_API_TOKEN"]
hdrs = {"Authorization": "Bearer " + token}

probe_sha = hashlib.sha256(b"probe-nonexistent-object").hexdigest()
wheel_sha = hashlib.sha256(open("dist/sqlite_utils-4.1.1-py3-none-any.whl","rb").read()).hexdigest()

def go(label, path):
    req = urllib.request.Request(base+path, headers=hdrs)
    try:
        with urllib.request.urlopen(req, timeout=8) as r:
            print(label, "-> HTTP", r.status, r.read().decode()[:400])
    except urllib.error.HTTPError as e:
        print(label, "-> HTTP", e.code, e.read().decode()[:200])

for oid, label in [(probe_sha, "probe-sha"), (wheel_sha, "wheel-sha")]:
    go(f"GET /v1/objects/{label}", f"/v1/objects/{oid}")
    go(f"GET /v1/objects/{label}/metadata", f"/v1/objects/{oid}/metadata")
go("GET obj-x hex", "/v1/objects/deadbeef")
go("GET obj obj_ prefix", "/v1/objects/obj_deadbeef")
EOF","description":"Test object-id route format via hex sha GETs"}

